test('e2e checkout webhook to Snowflake', async ({ page }) => {
  // seed checkout and id
  // trigger Stripe-like webhook payload twice with same id
  // wait for consumer to write to Snowflake
  // query Snowflake for the row and validate status/amount
  // verify dashboard shows updated status within 60s
